"""File-safety tests. All on temp folders with generated bytes - never on real photos."""
import errno
import hashlib
import os
import sqlite3
import subprocess
from pathlib import Path

import pytest

from burstbuster import HOLDING_DIR, fileops, scan

REPO = Path(__file__).resolve().parent.parent


@pytest.fixture(autouse=True)
def journal(tmp_path, monkeypatch):
    monkeypatch.setattr(fileops, "JOURNAL", tmp_path / "journal" / "journal.sqlite")


def _sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def _shot(*paths):
    return {"id": str(paths[0]),
            "stat": [[str(p), os.stat(p).st_size, os.stat(p).st_mtime_ns] for p in paths]}


def _make(root, name, data=None):
    p = Path(root) / name
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(data or os.urandom(2048))
    return p


def test_private_material_is_never_tracked():
    tracked = subprocess.run(["git", "ls-files"], cwd=REPO, capture_output=True, text=True, check=True).stdout
    # the only images allowed are the README screenshots in docs/ (generated demo images, no real photos)
    shots = {"docs/review.png", "docs/compare.png", "docs/no-face-burst.png", "docs/start.png"}
    bad = [f for f in tracked.splitlines()
           if f.startswith("testset/") or f == "burst-picking-and-catalog.md"
           or Path(f).suffix.lower() in scan.ALL_EXT | {".tif", ".tiff", ".webp"} and f not in shots]
    assert bad == []
    ignored = subprocess.run(["git", "check-ignore", "testset/x.JPG", "burst-picking-and-catalog.md", "a/b.HEIC"],
                             cwd=REPO, capture_output=True, text=True).stdout.splitlines()
    assert len(ignored) == 3


def test_set_aside_and_restore_round_trip_with_companions(tmp_path):
    root = tmp_path / "photos"
    files = [_make(root, "sub/IMG_1.JPG"), _make(root, "sub/IMG_1.MOV"), _make(root, "sub/IMG_1.JPG.xmp")]
    before = {str(p): _sha(p) for p in files}
    r = fileops.set_aside(root, "run1", [_shot(*files)])
    assert r["moved"] == [str(files[0])] and r["skipped"] == []
    assert not any(p.exists() for p in files)
    hold = Path(fileops.holding_dir(root, "run1"))
    assert (hold / "sub" / "IMG_1.MOV").exists()
    assert (hold / "where-these-came-from.json").exists()
    fileops.restore("run1")
    assert {str(p): _sha(p) for p in files} == before
    assert not (root / HOLDING_DIR).exists()  # empty holding folders are cleaned up


def test_never_overwrites_in_holding(tmp_path):
    root = tmp_path / "photos"
    a = _make(root, "IMG_2.JPG")
    clash = _make(Path(fileops.holding_dir(root, "run1")), "IMG_2.JPG", b"other")
    r = fileops.set_aside(root, "run1", [_shot(a)])
    assert r["moved"] == [] and "already" in r["skipped"][0][1]
    assert a.exists() and clash.read_bytes() == b"other"


def test_file_changed_since_scan_is_left_alone(tmp_path):
    root = tmp_path / "photos"
    a = _make(root, "IMG_3.JPG")
    shot = _shot(a)
    a.write_bytes(os.urandom(4096))
    r = fileops.set_aside(root, "run1", [shot])
    assert r["moved"] == [] and "changed" in r["skipped"][0][1]
    assert a.exists()


def test_shot_moves_all_or_nothing(tmp_path, monkeypatch):
    root = tmp_path / "photos"
    a, b = _make(root, "IMG_4.JPG"), _make(root, "IMG_4.CR3")
    real = fileops._move
    calls = []

    def flaky(src, dst):
        calls.append(src)
        if len(calls) == 2:
            raise PermissionError(13, "in use")
        real(src, dst)

    monkeypatch.setattr(fileops, "_move", flaky)
    r = fileops.set_aside(root, "run1", [_shot(a, b)])
    assert r["moved"] == [] and a.exists() and b.exists()


def test_restore_never_overwrites(tmp_path):
    root = tmp_path / "photos"
    a = _make(root, "IMG_5.JPG")
    fileops.set_aside(root, "run1", [_shot(a)])
    a.write_bytes(b"new photo with same name")
    r = fileops.restore("run1")
    assert r["restored"] == [] and a.read_bytes() == b"new photo with same name"


def test_crash_between_journal_and_rename_is_reconciled(tmp_path):
    root = tmp_path / "photos"
    a, b = _make(root, "IMG_6.JPG"), _make(root, "IMG_7.JPG")
    hold = Path(fileops.holding_dir(root, "run1"))
    hold.mkdir(parents=True)
    db = fileops._db()
    for p in (a, b):
        db.execute("INSERT INTO moves(run, root, shot, src, dst, size, mtime, state) VALUES (?,?,?,?,?,?,?, 'planned')",
                   ("run1", str(root), str(p), str(p), str(hold / p.name), 1, 1))
    db.commit()
    os.rename(a, hold / a.name)  # "crash" after the first rename, before the journal update
    assert fileops.reconcile() == []
    states = dict(sqlite3.connect(fileops.JOURNAL).execute("SELECT src, state FROM moves").fetchall())
    assert states == {str(a): "moved", str(b): "skipped"}
    fileops.restore("run1")
    assert a.exists() and b.exists()


def test_recycle_marks_only_files_that_left(tmp_path):
    root = tmp_path / "photos"
    a, b = _make(root, "IMG_8.JPG"), _make(root, "IMG_9.JPG")
    fileops.set_aside(root, "run1", [_shot(a), _shot(b)])
    hold = Path(fileops.holding_dir(root, "run1"))

    def fake_bin(paths):  # pretend the user cancelled after the first file
        os.remove(paths[0])
        return False

    r = fileops.recycle("run1", recycler=fake_bin)
    assert r["recycled"] == 1 and len(r["left"]) == 1 and r["error"]
    assert (hold / "IMG_9.JPG").exists()
    assert fileops.run_shots("run1") == [str(b)]


@pytest.mark.skipif(os.name != "nt", reason="Windows drive types; elsewhere send2trash picks the Trash")
def test_network_paths_have_no_recycle_bin():
    ok, why = fileops.recycle_supported(r"\\server\share\photos")
    assert not ok and "Network" in why


def test_scan_skips_links_and_holding_folder(tmp_path):
    root = tmp_path / "photos"
    _make(root, "IMG_10.JPG")
    _make(root, HOLDING_DIR + "/run/IMG_11.JPG")
    outside = tmp_path / "elsewhere"
    _make(outside, "IMG_12.JPG")
    if os.name == "nt":
        import _winapi
        _winapi.CreateJunction(str(outside), str(root / "junction"))  # symlinks need admin on Windows
    else:
        os.symlink(outside, root / "link")
    found = [Path(p).name for p, _ in scan.walk(root)]
    assert found == ["IMG_10.JPG"]


def test_companions_group_into_one_shot(tmp_path):
    root = tmp_path / "photos"
    for n in ("IMG_1.HEIC", "IMG_1.MOV", "IMG_1.AAE", "IMG_2.CR3", "IMG_2.JPG", "IMG_3.MOV"):
        _make(root, n)
    shots, _ = scan.inventory(root)
    by = {Path(s.primary).name: sorted(Path(f).name for f, _, _ in s.files) for s in shots}
    assert by == {"IMG_1.HEIC": ["IMG_1.AAE", "IMG_1.HEIC", "IMG_1.MOV"],
                  "IMG_2.JPG": ["IMG_2.CR3", "IMG_2.JPG"]}  # a lone video is never touched


def test_move_never_overwrites(tmp_path):
    """POSIX rename silently replaces the target; the move used for set-aside and restore must not."""
    a, b = _make(tmp_path, "a.jpg", b"keep-a"), _make(tmp_path, "b.jpg", b"keep-b")
    with pytest.raises(OSError):
        fileops._move(str(a), str(b))
    assert a.read_bytes() == b"keep-a" and b.read_bytes() == b"keep-b"
    fileops._move(str(a), str(tmp_path / "c.jpg"))
    assert not a.exists() and (tmp_path / "c.jpg").read_bytes() == b"keep-a"


def test_move_without_hard_links_still_never_overwrites(tmp_path, monkeypatch):
    """exFAT/FAT drives on macOS and Linux refuse hard links."""
    def no_link(src, dst):
        raise PermissionError(errno.EPERM, "Operation not permitted")

    a, b = _make(tmp_path, "a.jpg", b"keep-a"), _make(tmp_path, "b.jpg", b"keep-b")
    monkeypatch.setattr(fileops.os, "name", "posix")
    monkeypatch.setattr(fileops.os, "link", no_link)
    with pytest.raises(FileExistsError):
        fileops._move(str(a), str(b))
    assert b.read_bytes() == b"keep-b"
    fileops._move(str(a), str(tmp_path / "c.jpg"))
    assert not a.exists() and (tmp_path / "c.jpg").read_bytes() == b"keep-a"


def test_restore_is_all_or_nothing_per_shot(tmp_path):
    root = tmp_path / "photos"
    a, b = _make(root, "IMG_20.JPG"), _make(root, "IMG_20.MOV")
    fileops.set_aside(root, "run1", [_shot(a, b)])
    a.write_bytes(b"re-imported")  # the photo is back in the original folder, the video is not
    r = fileops.restore("run1", [str(a)])
    assert r["restored"] == [] and not b.exists()
    assert fileops.run_shots("run1") == [str(a)]  # both files still held, recorded as such


def test_restore_failure_puts_the_shot_back_in_holding(tmp_path, monkeypatch):
    root = tmp_path / "photos"
    a, b, c = _make(root, "IMG_21.JPG"), _make(root, "IMG_21.MOV"), _make(root, "IMG_22.JPG")
    fileops.set_aside(root, "run1", [_shot(a, b), _shot(c)])
    real, calls = fileops._move, []

    def locked(src, dst):  # the second file of the first shot is open in another program
        calls.append(src)
        if len(calls) == 2:
            raise PermissionError(13, "in use")
        real(src, dst)

    monkeypatch.setattr(fileops, "_move", locked)
    r = fileops.restore("run1")
    assert r["restored"] == [str(c)] and "could not move back" in r["skipped"][0][1]
    assert not a.exists() and not b.exists() and c.exists()
    assert fileops.run_shots("run1") == [str(a)]


def test_failed_rollback_keeps_the_journal_right(tmp_path, monkeypatch):
    root = tmp_path / "photos"
    a, b = _make(root, "IMG_23.JPG"), _make(root, "IMG_23.CR3")
    real, calls = fileops._move, []

    def flaky(src, dst):  # second file fails, and so does moving the first one back
        calls.append(src)
        if len(calls) >= 2:
            raise PermissionError(13, "in use")
        real(src, dst)

    monkeypatch.setattr(fileops, "_move", flaky)
    r = fileops.set_aside(root, "run1", [_shot(a, b)])
    assert r["moved"] == [] and b.exists() and not a.exists()
    states = dict(sqlite3.connect(fileops.JOURNAL).execute("SELECT src, state FROM moves").fetchall())
    assert states == {str(a): "moved", str(b): "failed"}  # restore can still bring it back


def test_files_removed_from_holding_by_hand_close_the_run(tmp_path):
    root = tmp_path / "photos"
    a = _make(root, "IMG_24.JPG")
    fileops.set_aside(root, "run1", [_shot(a)])
    os.remove(Path(fileops.holding_dir(root, "run1")) / "IMG_24.JPG")
    fileops.recycle("run1", recycler=lambda paths: True)
    assert fileops.open_runs() == []


def test_same_name_pictures_are_separate_shots(tmp_path):
    root = tmp_path / "photos"
    for n in ("photo.jpg", "photo.png", "photo.mov"):
        _make(root, n)
    shots, _ = scan.inventory(root)
    by = {Path(s.primary).name: sorted(Path(f).name for f, _, _ in s.files) for s in shots}
    assert by == {"photo.jpg": ["photo.jpg", "photo.mov"], "photo.png": ["photo.png"]}


def test_file_gone_after_the_walk_does_not_stop_copy_matching(tmp_path):
    root = tmp_path / "photos"
    for n in ("a.jpg", "b.jpg", "c.jpg"):
        _make(root, n, b"same")
    shots, _ = scan.inventory(root)
    os.remove(root / "c.jpg")
    assert [sorted(Path(s.primary).name for s in g) for g in scan.exact_duplicates(shots)] == [["a.jpg", "b.jpg"]]
